import { Accessor, Component, createEffect, createMemo, createSignal, For, onCleanup, onMount, Show } from "solid-js";

import { getRelationship } from "#core/ui/utilities/diplomacy-utilities.js";
import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CollapsibleContainer } from "#core/ui-next/components/collapsible-container.jsx";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SearchBar } from "#core/ui-next/components/search-bar.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { compareSettlementNames, compareSettlementTypes } from "#core/ui-next/utilities/settlement-utilities.js";
import { createLayoutComplete } from "#core/ui-next/utilities/solid-utilities.js";

import { GamepadTrayItem, GamepadTrayItemProvider } from "#base/ui-next/components/gamepad-tray-item-provider.jsx";
import { CommerceScreenBaseTabContent } from "#base/ui-next/screens/commerce/commerce-screen-base-tab-content.jsx";
import {
	TradeRouteData,
	TradeRouteSectionData,
	TradeRouteSortData,
	TradeRouteSortType,
	TradeRouteTabData,
	useCommerceScreenContext,
} from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { TRADE_ROUTE_CARD_MARGIN_RIGHT, TradeRouteCard } from "#base/ui-next/screens/commerce/trade-route-card.jsx";

const DEFAULT_CARD_WIDTH = Layout.pixelsToScreenPixels(512);

//#region TRADE ROUTES
export const TradeRoutesContainer: Component<TradeRouteTabData> = (props) => {
	const model = useCommerceScreenContext();

	const layoutComplete = createLayoutComplete();
	let cardsContainerRef: HTMLDivElement | undefined;
	let cardsContainerResizeObserver: ResizeObserver | undefined;
	let isApplyingMeasuredWidths = false;
	let hasScheduledWrapCheck = false;
	const [tradeRouteCardWidth, setTradeRouteCardWidth] = createSignal<string | undefined>(undefined);
	const [hasCheckedForWrap, setHasCheckedForWrap] = createSignal(false);
	const [numCardsInFirstRow, setNumCardsInFirstRow] = createSignal(0);

	const applyMeasuredWidths = (applyFunction: () => void) => {
		isApplyingMeasuredWidths = true;
		applyFunction();
		delayByFrame(() => {
			isApplyingMeasuredWidths = false;
		});
	};

	const scheduleWrapCheck = () => {
		if (hasScheduledWrapCheck) {
			return;
		}
		hasScheduledWrapCheck = true;
		delayByFrame(() => {
			hasScheduledWrapCheck = false;
			checkForWrap();
		});
	};

	onMount(() => {
		cardsContainerResizeObserver = new ResizeObserver(() => {
			if (isApplyingMeasuredWidths) {
				return;
			}
			scheduleWrapCheck();
		});

		if (cardsContainerRef) {
			cardsContainerResizeObserver.observe(cardsContainerRef);
			scheduleWrapCheck();
		}
	});

	onCleanup(() => {
		cardsContainerResizeObserver?.disconnect();
	});

	const checkForWrap = () => {
		if (!cardsContainerRef) {
			return;
		}

		const availableWidth = cardsContainerRef.clientWidth || 0;
		if (availableWidth <= 0) {
			return;
		}

		const rowCardCount = Math.max(
			1,
			Math.floor(
				(availableWidth + TRADE_ROUTE_CARD_MARGIN_RIGHT) / (DEFAULT_CARD_WIDTH + TRADE_ROUTE_CARD_MARGIN_RIGHT),
			),
		);

		const cardRows = Array.from(cardsContainerRef.querySelectorAll(".trade-route-cards-row")) as HTMLElement[];
		const hasWrappedRows = cardRows.some((row) => {
			const cards = row.querySelectorAll(".trade-route-card");
			return cards.length > rowCardCount;
		});

		if (!hasWrappedRows) {
			const needsWidthReset = tradeRouteCardWidth() !== undefined;
			const needsRowCountReset = numCardsInFirstRow() !== 0;
			if (needsWidthReset || needsRowCountReset) {
				applyMeasuredWidths(() => {
					if (needsWidthReset) {
						setTradeRouteCardWidth(undefined);
					}
					if (needsRowCountReset) {
						setNumCardsInFirstRow(0);
					}
					setHasCheckedForWrap(true);
				});
				return;
			}
			setHasCheckedForWrap(true);
			return;
		}

		const fittedWidth = (availableWidth - TRADE_ROUTE_CARD_MARGIN_RIGHT * rowCardCount) / rowCardCount;
		const nextWidth = Math.max(1, Math.floor(fittedWidth * 100) / 100) + "px";

		const needsRowCountUpdate = numCardsInFirstRow() !== rowCardCount;
		const needsWidthUpdate = tradeRouteCardWidth() !== nextWidth;
		if (needsRowCountUpdate || needsWidthUpdate) {
			applyMeasuredWidths(() => {
				if (needsRowCountUpdate) {
					setNumCardsInFirstRow(rowCardCount);
				}
				if (needsWidthUpdate) {
					setTradeRouteCardWidth(nextWidth);
				}
				setHasCheckedForWrap(true);
			});
			return;
		}
		setHasCheckedForWrap(true);
	};

	const tradeRouteSortItems: TradeRouteSortData[] = [
		{ type: TradeRouteSortType.SettlementType, locKey: "LOC_COMMERCE_RESOURCE_SORT_FILTER_DEFAULT_LABEL" },
		{ type: TradeRouteSortType.Resource, locKey: "LOC_COMMERCE_TRADE_SORT_BY_RESOURCE" },
		{ type: TradeRouteSortType.LeaderName, locKey: "LOC_COMMERCE_TRADE_SORT_BY_LEADER_NAME" },
		{ type: TradeRouteSortType.LeaderRelationship, locKey: "LOC_COMMERCE_TRADE_SORT_BY_LEADER_RELATIONSHIP" },
		{ type: TradeRouteSortType.SettlementName, locKey: "LOC_COMMERCE_SORT_BY_SETTLEMENT_NAME" },
	];

	const sortFunction = createMemo(() => {
		const sortingType = model.selectedTradeRouteSorting()?.type || TradeRouteSortType.Unset;

		function sortByResourceCount(a: TradeRouteData, b: TradeRouteData): number {
			return b.incomingResources.length - a.incomingResources.length;
		}

		function sortByLeaderName(a: TradeRouteData, b: TradeRouteData): number {
			if (a.leaderId === b.leaderId) {
				return 0;
			}
			const leaderA = Players.get(a.leaderId);
			const leaderB = Players.get(b.leaderId);
			if (!leaderA) {
				return 1;
			}
			if (!leaderB) {
				return -1;
			}
			if (leaderA.isMajor && leaderB.isMinor) {
				return -1;
			}
			if (leaderA.isMinor && leaderB.isMajor) {
				return 1;
			}
			const leaderANameString = Locale.compose(leaderA.leaderName);
			const leaderBNameString = Locale.compose(leaderB.leaderName);
			return Locale.compare(leaderANameString, leaderBNameString);
		}

		function sortByLeaderRelationship(a: TradeRouteData, b: TradeRouteData): number {
			if (a.leaderId === b.leaderId) {
				return 0;
			}
			const leaderA = Players.get(a.leaderId);
			const leaderB = Players.get(b.leaderId);
			if (!leaderA) {
				return 1;
			}
			if (!leaderB) {
				return -1;
			}
			if (leaderA.isMajor && leaderB.isMinor) {
				return -1;
			}
			if (leaderA.isMinor && leaderB.isMajor) {
				return 1;
			}

			const relationshipA = getRelationship(GameContext.localPlayerID, a.leaderId);
			const relationshipB = getRelationship(GameContext.localPlayerID, b.leaderId);
			return relationshipB.amount - relationshipA.amount;
		}

		function sortBySettlementName(a: TradeRouteData, b: TradeRouteData): number {
			return compareSettlementNames(a.cityID, b.cityID);
		}
		function sortBySettlementType(a: TradeRouteData, b: TradeRouteData): number {
			return compareSettlementTypes(a.cityID, b.cityID);
		}

		switch (sortingType) {
			case TradeRouteSortType.Resource: {
				return sortByResourceCount;
			}
			case TradeRouteSortType.LeaderName: {
				return sortByLeaderName;
			}
			case TradeRouteSortType.LeaderRelationship: {
				return sortByLeaderRelationship;
			}
			case TradeRouteSortType.SettlementName: {
				return sortBySettlementName;
			}
			case TradeRouteSortType.SettlementType: {
				return sortBySettlementType;
			}
		}
		return sortByResourceCount;
	});

	const [textFilter, setTextFilter] = createSignal<string>("");
	const tradeRouteSearchResults = createMemo(() => {
		return model.tradeRouteSearch(textFilter());
	});
	function tradeRouteIsIncludedInFilter(tradeRouteData: TradeRouteData) {
		if (textFilter() === "") {
			return true;
		}

		return tradeRouteSearchResults().has(ComponentID.toString(tradeRouteData.cityID));
	}

	createEffect(() => {
		props.tradeRouteSections.forEach((tradeRouteSection: TradeRouteSectionData) => {
			tradeRouteSection.tradeRoutes.sort(sortFunction());
		});
	});

	const [isSorting, setIsSorting] = createSignal(false);
	const [focusedTradeRoute, setFocusedTradeRoute] = createSignal<ComponentID | undefined>();
	const shouldAutoFocusDropdown = createMemo(() => isSorting());
	const autoFocusRouteIsPermitted = createMemo(() => !shouldAutoFocusDropdown());

	const firstVisibleSectionIndex = createMemo(() => {
		let visibleSectionIndex = -1;
		props.tradeRouteSections.forEach((section, index) => {
			if (visibleSectionIndex > -1) {
				return;
			}
			if (section.tradeRoutes.length > 0) {
				visibleSectionIndex = index;
			}
		});
		return visibleSectionIndex;
	});

	const shouldAutoFocusRoute = (routeCityId: ComponentID, sectionIndex: number, routeIndex: number) => {
		if (!autoFocusRouteIsPermitted()) {
			return false;
		}

		if (!layoutComplete()) {
			return false;
		}

		if (focusedTradeRoute() === undefined) {
			return sectionIndex === firstVisibleSectionIndex() && routeIndex === 0;
		}

		return ComponentID.isMatch(focusedTradeRoute()!, routeCityId);
	};

	const gamepadTrayItems: Accessor<GamepadTrayItem[]> = createMemo(() => {
		if (model.selectedTradeRouteId()) {
			const selectedCity = Cities.get(model.selectedTradeRouteId()!);
			if (selectedCity) {
				const deselectRouteLabel = Locale.compose(
					"LOC_COMMERCE_GAMEPAD_STOP_VIEWING_CONTAINER_HINT",
					Locale.compose(selectedCity.name),
				);
				return [
					{
						hotkeyAction: "cancel",
						name: "cancel-traderoute-edit",
						navTrayText: deselectRouteLabel,
						onActivate: () => model.setSelectedTradeRouteId(),
					},
				] as GamepadTrayItem[];
			}
			console.warn(
				"commerce-screen-trade-tab.tsx: When getting gamepadTrayItems, couldn't find city with ID",
				model.selectedTradeRouteId(),
			);
			return [];
		} else {
			const items: GamepadTrayItem[] = [
				{
					hotkeyAction: "shell-action-2",
					name: "sort-traderoutes",
					navTrayText: "LOC_COMMERCE_SORT_LABEL",
					onActivate: () => {
						setIsSorting((prev) => !prev);
					},
				},
			];
			if (focusedTradeRoute()) {
				const focusedCity = Cities.get(focusedTradeRoute()!);
				if (focusedCity) {
					const selectRouteLabel = Locale.compose(
						"LOC_COMMERCE_GAMEPAD_VIEW_CONTAINER_HINT",
						Locale.compose(focusedCity.name),
					);
					items.push({
						hotkeyAction: "accept",
						name: "traderoute-edit",
						navTrayText: selectRouteLabel,
						// activate handled by activatable in trade-route-card.tsx
					});
				}
			}
			return items;
		}
	});

	return (
		<SpatialSlot
			name="Commerce-Screen-Trade-Tab"
			class="flex-auto"
		>
			<CommerceScreenBaseTabContent
				title="LOC_COMMERCE_TRADE_ROUTES_TITLE"
				description="LOC_COMMERCE_TRADE_ROUTES_DESCRIPTION"
				headerBar={
					<div class="top-0 right-3 flex flex-row items-center">
						<Show when={ViewExperience() === UIViewExperience.Desktop && !IsControllerActive()}>
							<SearchBar
								value={textFilter}
								setValue={setTextFilter}
								class="mr-4"
							/>
						</Show>
						<div class="font-title uppercase text-secondary">
							<L10n.Compose text="LOC_COMMERCE_SORT_LABEL" />
						</div>
						<AudioContextProvider segment="Filters">
							<Dropdown
								class="ml-2 w-60 pointer-events-auto grow-0 min-h-14"
								selectedItemTemplate={(item) => (
									<div class="ml-2">
										<L10n.Compose text={item.locKey} />
									</div>
								)}
								onItemSelected={(item) => model.setSelectedTradeRouteSorting(item)}
								defaultValue={tradeRouteSortItems[0]}
								disableFocus={!isSorting()}
								autoFocus={shouldAutoFocusDropdown()}
								onFocus={() => setFocusedTradeRoute()}
							>
								<For each={tradeRouteSortItems}>
									{(item) => (
										<DropdownItem value={item}>{<L10n.Compose text={item.locKey} />}</DropdownItem>
									)}
								</For>
							</Dropdown>
						</AudioContextProvider>
					</div>
				}
			>
				<GamepadTrayItemProvider
					class="flex-auto"
					name="traderoute-gamepad-items"
					items={gamepadTrayItems}
				>
					<ScrollArea
						class="flex-auto"
						useProxy
					>
						<div
							ref={cardsContainerRef}
							class="flex flex-row flex-wrap flex-auto relative"
						>
							<For each={props.tradeRouteSections}>
								{(section, index) => (
									<CollapsibleContainer
										{...section.collapsibleContainerData}
										class="text-secondary w-full mb-2"
										headerClass="font-title fxs-header"
										disableFocus={model.selectedTradeRouteId() !== undefined || isSorting()}
									>
										<div class="trade-route-cards-row flex-row flex flex-wrap w-full items-start">
											<Show
												when={section.tradeRoutes.length == 0 && section.emptyDescription != ""}
											>
												<div class="w-full flex flex-row justify-center items-center mt-2 text-accent-2 p-4">
													<L10n.Compose text={section.emptyDescription} />
												</div>
											</Show>

											<For each={section.tradeRoutes}>
												{(tradeRoute, subIndex) => (
													<Show when={tradeRouteIsIncludedInFilter(tradeRoute)}>
														<TradeRouteCard
															tradeRoute={tradeRoute}
															onFocus={() => setFocusedTradeRoute(tradeRoute.cityID)}
															autoFocus={shouldAutoFocusRoute(
																tradeRoute.cityID,
																index(),
																subIndex(),
															)}
															disabled={isSorting()}
															class={`${hasCheckedForWrap() ? "opacity-100" : "opacity-0"}`}
															style={{
																width:
																	tradeRouteCardWidth() !== undefined
																		? tradeRouteCardWidth()
																		: DEFAULT_CARD_WIDTH + "px",
																"margin-right":
																	(numCardsInFirstRow() > 0 &&
																		(subIndex() + 1) % numCardsInFirstRow() !==
																			0) ||
																	(numCardsInFirstRow() === 0 && hasCheckedForWrap())
																		? TRADE_ROUTE_CARD_MARGIN_RIGHT + "px"
																		: "0px",
															}}
														/>
													</Show>
												)}
											</For>
										</div>
									</CollapsibleContainer>
								)}
							</For>
						</div>
					</ScrollArea>
				</GamepadTrayItemProvider>
			</CommerceScreenBaseTabContent>
		</SpatialSlot>
	);
};
//#endregion
